-- Rewrites the stored key of every compendium reference-work entry to the wording `citationText` renders today: a headword follows
-- ", under " where it once followed ", s.v. ". A reference's `seed_key` is that rendered text and the seed finds a source by it alone,
-- so the rows written before the change were never found again, and the seed inserted a second copy beside each one it was asked to
-- cite. Only a live compendium row of kind "entry" is touched (a workspace's own source has no seed row to find), and only the first
-- ", s.v. " in the key, which is the connector; the title is never rewritten.
--
-- A "twin" is another live row already holding the rewritten key. Where there is none the key is rewritten in place and the row keeps
-- its id and its links. Where there is one, the old row's live links move to the twin, a link the twin already holds for the same
-- entry or form is soft-deleted instead (the unique index allows one live link per owner and source, whatever the locator), and the
-- old row is soft-deleted. A link already deleted stays on the row it was deleted from. A key rewrite or a moved link keeps its
-- `updated_by`, so a person's edit still reads as theirs to the seed.
-- A SQL migration cannot revalidate the unstable_cache "compendium" tag; the deploy that runs it starts a fresh cache.
UPDATE "reference_links" l SET "deleted_at" = now(), "deleted_by" = '00000000-0000-0000-0000-000000000001', "updated_by" = '00000000-0000-0000-0000-000000000001' FROM "references" o JOIN "references" t ON t."seed_key" = regexp_replace(o."seed_key", ', s\.v\. ', ', under ') AND t."id" <> o."id" AND t."deleted_at" IS NULL WHERE l."reference_id" = o."id" AND l."deleted_at" IS NULL AND o."workspace_id" IS NULL AND o."deleted_at" IS NULL AND o."kind" = 'entry' AND o."seed_key" LIKE '%, s.v. %' AND EXISTS (SELECT 1 FROM "reference_links" k WHERE k."reference_id" = t."id" AND k."deleted_at" IS NULL AND k."ingredient_id" IS NOT DISTINCT FROM l."ingredient_id" AND k."deity_id" IS NOT DISTINCT FROM l."deity_id" AND k."deity_tradition_id" IS NOT DISTINCT FROM l."deity_tradition_id" AND k."celestial_body_id" IS NOT DISTINCT FROM l."celestial_body_id" AND k."zodiac_sign_id" IS NOT DISTINCT FROM l."zodiac_sign_id" AND k."ingredient_variant_id" IS NOT DISTINCT FROM l."ingredient_variant_id");--> statement-breakpoint
UPDATE "reference_links" l SET "reference_id" = t."id" FROM "references" o JOIN "references" t ON t."seed_key" = regexp_replace(o."seed_key", ', s\.v\. ', ', under ') AND t."id" <> o."id" AND t."deleted_at" IS NULL WHERE l."reference_id" = o."id" AND l."deleted_at" IS NULL AND o."workspace_id" IS NULL AND o."deleted_at" IS NULL AND o."kind" = 'entry' AND o."seed_key" LIKE '%, s.v. %';--> statement-breakpoint
UPDATE "references" o SET "deleted_at" = now(), "deleted_by" = '00000000-0000-0000-0000-000000000001', "updated_by" = '00000000-0000-0000-0000-000000000001' WHERE o."workspace_id" IS NULL AND o."deleted_at" IS NULL AND o."kind" = 'entry' AND o."seed_key" LIKE '%, s.v. %' AND EXISTS (SELECT 1 FROM "references" t WHERE t."seed_key" = regexp_replace(o."seed_key", ', s\.v\. ', ', under ') AND t."id" <> o."id" AND t."deleted_at" IS NULL);--> statement-breakpoint
UPDATE "references" SET "seed_key" = regexp_replace("seed_key", ', s\.v\. ', ', under ') WHERE "workspace_id" IS NULL AND "deleted_at" IS NULL AND "kind" = 'entry' AND "seed_key" LIKE '%, s.v. %';
